export const BODY: string = "\n<p>BMP Windows کا سب سے پرانا تصویری فارمیٹ ہے، اور سب سے ضائع کرنے والا بھی۔ BMP اسکرین شاٹ 20MB کا ہو سکتا ہے، جبکہ وہی تصویر JPG میں 500KB کی ہوتی ہے، بغیر نظر آنے والی کوالٹی کے فرق کے۔</p>\n<p>BMP کو JPG میں بدلنا پرانی Windows تصاویر کو دوبارہ قابلِ استعمال بنانے کا تیز ترین طریقہ ہے۔ فائل 90 فیصد یا اس سے زیادہ سکڑ جاتی ہے، اور نتیجہ ہر جگہ کھلتا ہے۔</p>\n<p>اس گائیڈ میں بتایا گیا ہے کہ BMP فائلیں اتنی بڑی کیوں ہوتی ہیں، تبدیلی کیسے کام کرتی ہے، اور JPG کب درست ہدف ہوتا ہے۔</p>\n<h2 id=\"what-is-bmp\">BMP کیا ہے؟</h2>\n<p>BMP کا مطلب ہے bitmap، اور یہ Windows کا مقامی تصویری فارمیٹ ہے، جو 1990 کی دہائی سے چلا آ رہا ہے۔ یہ ہر پکسل کو بالکل محفوظ کرتا ہے، بہت کم یا بغیر کمپریشن کے۔</p>\n<p>یہ فارمیٹ اس وقت کے لیے ڈیزائن کیا گیا تھا جب پروسیسر سست تھے اور اسٹوریج سادہ تھا۔ پکسلز کو خام محفوظ کرنا تیز تھا، اور کوئی فائل سائز کی فکر نہیں کرتا تھا۔</p>\n<p>BMP فائلیں پرانے Windows سافٹ ویئر، اسکینر، اور ڈیجیٹل کیمروں سے آتی ہیں جو اس فارمیٹ میں محفوظ کرتے ہیں۔ یہ پرانی ایپلیکیشنز کے اسکرین شاٹس کے طور پر بھی ظاہر ہوتی ہیں۔</p>\n<p>یہ فارمیٹ کئی رنگ گہرائی سپورٹ کرتا ہے، 1 بٹ سیاہ سفید سے لے کر 24 بٹ مکمل رنگ تک۔ پرانی فائلیں 8 بٹ پیلیٹ استعمال کر سکتی ہیں، جبکہ نئی عام طور پر 24 بٹ ہوتی ہیں۔</p>\n<h2 id=\"why-bmp-is-huge\">BMP فائلیں اتنی بڑی کیوں ہوتی ہیں؟</h2>\n<p>BMP پکسلز کو تقریباً بغیر کمپریشن کے محفوظ کرتا ہے۔ 24 بٹ رنگ پر 1920 بائی 1080 اسکرین شاٹ کو صرف پکسلز کے لیے 6MB سے زیادہ چاہیے ہوتا ہے، ہیڈر کے علاوہ، اور سکڑنے کا کوئی طریقہ نہیں۔</p>\n<p>JPG اسی اسکرین شاٹ کو 500KB تک کمپریس کرتا ہے، وہ تفصیل ضائع کر کے جو آنکھ بمشکل محسوس کرتی ہے۔ فرق تصویر نہیں بلکہ کمپریشن ہے۔</p>\n<p>فلیٹ علاقے BMP میں سب سے زیادہ جگہ ضائع کرتے ہیں۔ سفید پس منظر جسے JPG چند بائٹ میں محفوظ کرتا ہے وہ BMP میں ہزاروں بائٹ لیتا ہے، کیونکہ ہر سفید پکسل الگ لکھا جاتا ہے۔</p>\n<p>شور بھی جگہ ضائع کرتا ہے۔ کاغذ کے دانے والا اسکین شدہ تصویر میں لامتناہی چھوٹی تبدیلیاں ہوتی ہیں، اور BMP ان میں سے ہر ایک کو بالکل محفوظ کرتا ہے، جبکہ JPG انہیں سادہ کر دیتا ہے۔</p>\n<h2 id=\"how-conversion-works\">BMP سے JPG تبدیلی کیسے کام کرتی ہے؟</h2>\n<p>کنورٹر BMP فائل کو سیدھا آپ کے براؤزر میں پڑھتا ہے۔ BMP ڈی کوڈنگ براؤزرز میں بنی ہوئی ہے، اس لیے کسی اضافی ڈی کوڈر کی ضرورت نہیں، اور فائل فوراً لوڈ ہو جاتی ہے۔</p>\n<p>پکسلز کینوس پر کھینچے جاتے ہیں اور آپ کی چنی ہوئی کوالٹی پر JPG کے طور پر انکوڈ ہوتے ہیں۔ تصویر اپنے ابعاد رکھتی ہے اور ایک جیسی لگتی ہے، جبکہ فائل ڈرامائی طور پر سکڑ جاتی ہے۔</p>\n<p>ہر فائل 25MB تک قبول کی جاتی ہے، جو بغیر کسی تیاری کے بڑے اسکرین شاٹس اور اعلیٰ ریزولوشن اسکین کو پورا کرتی ہے۔</p>\n<p>تبدیلی مکمل طور پر آپ کے ڈیوائس پر ہوتی ہے۔ آپ کے اسکین اور اسکرین شاٹس آپ کے کمپیوٹر سے کبھی باہر نہیں جاتے، جو ذاتی اور کام کی فائلوں کے لیے اہمیت رکھتا ہے۔</p>\n<h2 id=\"quality-settings\">کوالٹی سیٹنگز جو کام کرتی ہیں</h2>\n<p>اسکین شدہ دستاویزات کے لیے 85 سے 90 فیصد کوالٹی متن کو پڑھنے کے قابل رکھتی ہے جبکہ فائل کو نمایاں طور پر چھوٹا کرتی ہے۔ چھوٹی پرنٹ کم سیٹنگ پر دھندلی ہو جاتی ہے، اس لیے اونچا رہیں۔</p>\n<p>اسکرین شاٹس کے لیے 85 فیصد بہترین نقطہ ہے۔ انٹرفیس صاف رہتا ہے، فائل 90 فیصد سکڑ جاتی ہے، اور تصویر صاف لگتی ہے۔</p>\n<p>BMP کے طور پر محفوظ شدہ تصاویر کے لیے 80 سے 85 فیصد درست حد ہے۔ تصویر صاف لگتی ہے، اور فائل BMP سائز کا حصہ ہوتی ہے۔</p>\n<p>سائز کی حد والے فارم کے لیے جانے والی تصاویر کے لیے 85 سے شروع کریں اور آہستہ آہستہ نیچے جائیں۔ ہر قدم کے بعد سائز چیک کریں، اور جیسے ہی فائل فٹ ہو جائے رک جائیں۔</p>\n<h2 id=\"colour-depth\">رنگ گہرائی کے ساتھ کیا ہوتا ہے؟</h2>\n<p>24 بٹ BMP صاف JPG میں بدلتا ہے، کیونکہ JPG بھی 24 بٹ رنگ استعمال کرتا ہے۔ اصل میں لاکھوں رنگ JPG کمپریشن کی اجازت تک محفوظ رہتے ہیں۔</p>\n<p>رنگ پیلیٹ والا 8 بٹ BMP بھی بدلتا ہے۔ پیلیٹ رنگ JPG میں عام RGB رنگ بن جاتے ہیں، اور تصویر ایک جیسی لگتی ہے۔</p>\n<p>1 بٹ سیاہ سفید BMP، جیسے فیکس اسکین، صرف سیاہ سفید پکسل والی JPG میں بدلتا ہے۔ فائل بہت زیادہ سکڑ جاتی ہے، کیونکہ تصویر اتنی سادہ ہوتی ہے۔</p>\n<p>پرانے 1 بٹ اور 8 بٹ BMP فائلیں مکمل سپورٹ ہوتی ہیں۔ کنورٹر پیلیٹ اور پکسل ڈیٹا پڑھتا ہے، اور JPG تصویر کو وفاداری سے دوبارہ بناتا ہے۔</p>\n<h2 id=\"scanned-bmp-files\">اسکین شدہ BMP فائلیں اتنی اچھی طرح کیوں کمپریس ہوتی ہیں</h2>\n<p>اسکین شدہ BMP فائلیں زیادہ تر گہرے متن والا سفید کاغذ ہوتی ہیں۔ یہ سادگی JPG کے طور پر خوبصورتی سے کمپریس ہوتی ہے، کیونکہ بڑے فلیٹ علاقوں کو بہت کم بائٹ چاہیے ہوتے ہیں۔</p>\n<p>10MB اسکین شدہ BMP 85 فیصد کوالٹی پر 300KB JPG بن سکتا ہے۔ یہ 97 فیصد بچت ہے، اور متن پھر بھی مکمل پڑھنے کے قابل رہتا ہے۔</p>\n<p>کاغذ کا دانہ واحد چیز ہے جو کمپریشن کے خلاف مزاحمت کرتی ہے۔ شور والا اسکین صاف اسکین سے کم بچاتا ہے، حالانکہ بچت پھر بھی ڈرامائی ہوتی ہے۔</p>\n<p>اسکین شدہ BMP فائلوں کے آرکائیو کے لیے JPG میں بدلنا گیگا بائٹ اسٹوریج آزاد کر سکتا ہے۔ جو فولڈر ڈرائیو بھرتا تھا وہ USB اسٹک پر فٹ ہونے والا فولڈر بن جاتا ہے۔</p>\n<h2 id=\"transparency-myth\">کیا BMP میں شفافیت ہوتی ہے؟</h2>\n<p>معیاری BMP فائلیں شفافیت سپورٹ نہیں کرتیں۔ ہر پکسل کا ٹھوس رنگ ہوتا ہے، اور شفاف جگہوں کے لیے کوئی الفا چینل نہیں ہوتا۔</p>\n<p>کچھ نایاب 32 بٹ BMP فائلیں الفا چینل لے جاتی ہیں، مگر زیادہ تر سافٹ ویئر اسے نظر انداز کرتا ہے۔ عملی طور پر BMP تصاویر ہمیشہ مکمل غیر شفاف ہوتی ہیں۔</p>\n<p>اس لیے JPG میں بدلنے سے شفافیت پر کچھ نہیں کھوتا۔ JPG بھی غیر شفاف ہوتا ہے، اور تصویر بالکل ویسی ہی لگتی ہے جیسی BMP تھی۔</p>\n<p>اگر آپ کو شفافیت چاہیے تو اس کے بجائے BMP کو PNG میں بدلیں۔ <a href=\"/ur/tasveer-convert-karein/\">Image Converter</a> یہ کر سکتا ہے، حالانکہ BMP میں شاذ و نادر ہی محفوظ کرنے کے قابل شفافیت ہوتی ہے۔</p>\n<h2 id=\"batch-converting\">BMP اسکین کے فولڈر کو بیچ میں بدلنا</h2>\n<p>آپ BMP اسکین کے پورے فولڈر کو ایک بیچ میں بدل سکتے ہیں۔ ہر فائل آزادانہ بدلتی ہے، اور ZIP ان سب کو رکھتا ہے۔</p>\n<p>پورے فولڈر کے لیے ایک ہی کوالٹی سیٹنگ استعمال کریں۔ مستقل مزاجی اہمیت رکھتی ہے جب اسکین ایک ہی آرکائیو یا دستاویز سیٹ سے تعلق رکھتے ہوں۔</p>\n<p>تبدیل کرنے کے بعد بیچ خلاصہ دیکھیں۔ BMP اسکین کا فولڈر اکثر مجموعی طور پر 95 فیصد سکڑ جاتا ہے، جو ڈرامائی نمبر ہے جو محنت کا جواز دیتا ہے۔</p>\n<p>تبدیل کرنے کے بعد BMP اصل کو آرکائیو فولڈر میں رکھیں۔ وہ ماسٹر ہیں، اور اگر آپ کو بعد میں مختلف فارمیٹ چاہیے ہو تو آپ انہیں ہمیشہ دوبارہ بدل سکتے ہیں۔</p>\n<h2 id=\"checking-quality\">ڈاؤن لوڈ سے پہلے کوالٹی چیک کرنا</h2>\n<p>کسی بھی کارڈ پر Compare پر کلک کریں تاکہ BMP اور JPG کو آمنے سامنے دیکھ سکیں۔ اسپلٹ ہینڈل کو تصویر پر کھینچیں اور متن اور باریک تفصیل پر زوم کریں۔</p>\n<p>سب سے چھوٹا متن پہلے چیک کریں، کیونکہ یہ JPG کمپریشن سے سب سے زیادہ متاثر ہوتا ہے۔ 85 فیصد کوالٹی پر اسکین شدہ دستاویز اپنی پرنٹ کو مکمل پڑھنے کے قابل رکھنی چاہیے۔</p>\n<p>اگر متن نرم لگے تو کوالٹی پانچ پوائنٹ بڑھائیں اور دوبارہ بدلیں۔ اصل BMP قطار میں رہتا ہے، اس لیے آپ کو دوبارہ اپ لوڈ کرنے کی ضرورت نہیں۔</p>\n<p>بیچ کے لیے ہر فائل کے بجائے تین یا چار نمائندہ فائلیں چیک کریں۔ اگر وہ اچھی لگیں تو باقی بھی اچھی ہوں گی، کیونکہ سیٹنگ ایک ہی ہے۔</p>\n<h2 id=\"bmp-vs-png-decision\">BMP سے JPG یا BMP سے PNG؟</h2>\n<p>جب مقصد چھوٹی فائلیں ہوں تو JPG چنیں۔ JPG میں بدلا BMP اسکین 90 فیصد یا اس سے زیادہ سکڑ جاتا ہے، جبکہ PNG ورژن کہیں کم سکڑتا ہے۔</p>\n<p>جب تصویر کو کئی بار ایڈٹ کیا جائے گا تو PNG چنیں۔ PNG لاس لیس ہے، اس لیے دہرائے جانے والے محفوظ کرنے سے یہ خراب نہیں ہوتا، جبکہ ہر JPG محفوظ کرنے سے کچھ نقصان بڑھتا ہے۔</p>\n<p>فارم یا ای میل کو جانے والے اسکرین شاٹس اور اسکین کے لیے JPG چنیں۔ چھوٹی فائل تیزی سے بھیجی جاتی ہے اور سائز کی حدوں سے ٹکرائے بغیر اپ لوڈ ہوتی ہے۔</p>\n<p>لائن آرٹ اور ڈایاگرام کے لیے PNG چنیں جہاں ہر پکسل بالکل رہنا چاہیے۔ لاس لیس فارمیٹ پتلی لکیروں کو JPG سے بہتر محفوظ رکھتا ہے۔</p>\n<h2 id=\"where-jpg-works\">بدلی ہوئی JPG کہاں کام کرتی ہے</h2>\n<p>بدلی ہوئی JPG کسی بھی پروگرام میں، کسی بھی ڈیوائس پر کھلتی ہے۔ Windows Photos، macOS Preview، WhatsApp، اور پرانے پرنٹر سب JPG کو بغیر کسی پریشانی کے سنبھالتے ہیں۔</p>\n<p>یہ ہر فارم، پورٹل، اور ویب سائٹ پر اپ لوڈ ہوتی ہے جو JPG کو قبول شدہ فارمیٹ درج کرتی ہے۔ سرکاری سسٹم، نوکری بورڈ، اور پرنٹ شاپس سب JPG لیتے ہیں۔</p>\n<p>یہ بغیر پریشانی کے ای میل سے منسلک ہوتی ہے۔ BMP اٹیچمنٹ اکثر بھیجنے کے لیے بہت بڑی ہوتی ہے، جبکہ JPG ورژن حدوں سے ٹکرائے بغیر گزر جاتا ہے۔</p>\n<p>یہ کسی بھی پرنٹر پر صاف چھپتی ہے۔ پرنٹر JPG کی توقع رکھتے ہیں، اور بدلی ہوئی JPG اسی کوالٹی والی کیمرہ JPG جیسی ہی چھپتی ہے۔</p>\n<h2 id=\"common-problems\">عام مسائل اور ان کا حل</h2>\n<p>اگر BMP فائل تبدیل ہونے میں ناکام ہو تو وہ غیر معمولی کمپریشن یا غیر سپورٹ شدہ رنگ گہرائی استعمال کر سکتی ہے۔ پہلے اسے Windows Paint میں کھولنے کی کوشش کریں، اور اسے معیاری BMP کے طور پر دوبارہ محفوظ کریں۔</p>\n<p>اگر متن دھندلا لگے تو کوالٹی بہت کم تھی۔ سلائیڈر کو 90 فیصد تک بڑھائیں اور اصل BMP سے دوبارہ بدلیں۔</p>\n<p>اگر JPG BMP سے بمشکل چھوٹی ہو تو تصویر شاید بہت سادہ یا بہت شور والی ہے۔ سادہ تصویر میں کمپریس کرنے کے لیے کم ہوتا ہے، جبکہ شور کمپریشن کے خلاف مزاحمت کرتا ہے۔</p>\n<p>اگر رنگ غلط لگیں تو BMP غیر معمولی پیلیٹ استعمال کر سکتا ہے۔ نتیجہ احتیاط سے چیک کریں، اور اگر ماخذ فائل مشکوک ہو تو تازہ ایکسپورٹ سے بدلیں۔</p>\n<h2 id=\"bmp-from-old-scanners\">پرانے اسکینرز سے BMP فائلیں</h2>\n<p>پرانے اسکینر اکثر ڈیفالٹ طور پر BMP میں محفوظ کرتے ہیں، جو سادہ دستاویزات کے لیے بہت بڑی فائلیں بناتے ہیں۔ ایک اسکین شدہ صفحہ BMP میں 10MB کا ہو سکتا ہے، جبکہ وہی صفحہ JPG میں 300KB کا ہوتا ہے۔</p>\n<p>اسکین کو 85 سے 90 فیصد کوالٹی پر JPG میں بدلیں۔ متن پڑھنے کے قابل رہتا ہے، فائلیں 95 فیصد سکڑ جاتی ہیں، اور آرکائیو ڈسک جگہ کے حصے پر فٹ ہو جاتا ہے۔</p>\n<p>اسکین کے پورے آرکائیو کے لیے پچاس کے بیچ میں بدلیں۔ ہر بیچ ہمواری سے چلتا ہے، اور ایک بیچ میں ناکامی دوسروں کو متاثر نہیں کرتی۔</p>\n<p>تبدیل کرنے کے بعد BMP اصل کو آرکائیو فولڈر میں رکھیں۔ وہ ماسٹر ہیں، اور اگر آپ کو بعد میں مختلف فارمیٹ چاہیے ہو تو آپ انہیں ہمیشہ دوبارہ بدل سکتے ہیں۔</p>\n<p>مستقبل کے اسکین کے لیے اسکینر سیٹنگ چیک کریں۔ اسکینر کو JPG یا PDF پر بدلنے سے تبدیلی کا مرحلہ مکمل ختم ہو جاتا ہے، اور فائلیں شروع سے درست فارمیٹ میں آتی ہیں۔</p>\n<h2 id=\"bmp-from-legacy-software\">پرانے سافٹ ویئر سے BMP فائلیں</h2>\n<p>پرانا Windows سافٹ ویئر اکثر تصاویر صرف BMP کے طور پر محفوظ کرتا ہے، کیونکہ یہ فارمیٹ اس وقت معیار تھا جب سافٹ ویئر لکھا گیا تھا۔ ان فائلوں کو استعمال سے پہلے بدلنا چاہیے۔</p>\n<p>پرانے پروگرام سے تصویر کو BMP کے طور پر ایکسپورٹ کریں، پھر اسے JPG میں بدلیں۔ دو مرحلہ والا راستہ ہر فائل کے لیے کام کرتا ہے، چاہے سافٹ ویئر کتنا پرانا ہو۔</p>\n<p>تبدیل کرنے کے بعد تصویر چیک کریں، کیونکہ پرانا سافٹ ویئر کبھی کبھی غیر معمولی BMP قسم بناتا ہے۔ JPG پر فوری نظر تصدیق کرتی ہے کہ رنگ اور مواد بچ گئے۔</p>\n<p>پرانے سافٹ ویئر سے بڑی کلیکشن کے لیے بیچ میں بدلیں اور اصل رکھیں۔ پچاس فائلوں کا بیچ منٹوں میں ہو جاتا ہے، اور اصل آرکائیو میں محفوظ رہتے ہیں۔</p>\n<p>اگلے شخص کے لیے تبدیلی کی سیٹنگ دستاویز کریں۔ ایک لائن نوٹ ملے ہوئے فارمیٹس میں آہستہ بہاؤ کو روکتا ہے جو ہر پرانی منتقلی کو پریشان کرتا ہے۔</p>\n<h2 id=\"bmp-screenshots-games\">گیمز سے BMP اسکرین شاٹس</h2>\n<p>پرانے گیمز اسکرین شاٹس کو BMP فائلوں کے طور پر محفوظ کرتے ہیں، اور وہ فائلیں بہت بڑی ہوتی ہیں۔ 1920 بائی 1080 اسکرین شاٹ BMP میں 6MB سے زیادہ ہوتا ہے، جبکہ وہی تصویر JPG میں 500KB کی ہوتی ہے۔</p>\n<p>اسکرین شاٹس کو 85 فیصد کوالٹی پر JPG میں بدلیں۔ گیم گرافکس تیز رہتے ہیں، فائلیں 90 فیصد سکڑ جاتی ہیں، اور کلیکشن ڈسک جگہ کے حصے پر فٹ ہو جاتی ہے۔</p>\n<p>اسکرین شاٹ کلیکشن کے لیے گیم کے حساب سے بیچ میں بدلیں۔ ہر بیچ کو ایک ہی سیٹنگ ملتی ہے، اور فولڈر عنوان کے حساب سے منظم رہتے ہیں۔</p>\n<p>سب سے اہم اسکرین شاٹس کے لیے BMP اصل رکھیں۔ پسندیدہ لمحہ لاس لیس ماسٹر کا حقدار ہوتا ہے، جبکہ JPG کاپیاں شیئرنگ کے لیے ہوتی ہیں۔</p>\n<p>JPG ورژن آن لائن شیئر کریں، کیونکہ گیمنگ فورم اور سوشل میڈیا JPG کو مقامی طور پر سنبھالتے ہیں۔ BMP اپ لوڈ ناکام ہو سکتا ہے یا سست کنکشن پر بہت زیادہ وقت لے سکتا ہے۔</p>\n<h2 id=\"bmp-from-cameras\">ڈیجیٹل کیمروں سے BMP فائلیں</h2>\n<p>کچھ ڈیجیٹل کیمرے تصاویر کو BMP کے طور پر محفوظ کرتے ہیں، خاص طور پر پرانے ماڈل اور صنعتی کیمرے۔ وہ فائلیں بڑی ہوتی ہیں، اور انہیں JPG میں بدلنے سے وہ قابلِ استعمال بن جاتی ہیں۔</p>\n<p>کیمرہ BMP کو 85 فیصد کوالٹی پر JPG میں بدلیں۔ تصاویر صاف لگتی ہیں، فائلیں ڈرامائی طور پر سکڑ جاتی ہیں، اور تصاویر کسی بھی فوٹو ایپ میں کھلتی ہیں۔</p>\n<p>مستقبل کی شوٹ کے لیے کیمرہ سیٹنگ چیک کریں۔ کیمرے کو JPG پر بدلنے سے تبدیلی کا مرحلہ مکمل ختم ہو جاتا ہے، اور فائلیں شروع سے درست فارمیٹ میں آتی ہیں۔</p>\n<p>جن تصاویر کو آپ ایڈٹ کرنے کا ارادہ رکھتے ہیں ان کے لیے PNG کاپی ماسٹر رکھیں۔ لاس لیس فارمیٹ دہرائے جانے والے ایڈٹ سے بچ جاتا ہے، جبکہ ہر JPG محفوظ کرنے سے کچھ نقصان بڑھتا ہے۔</p>\n<p>بدلی ہوئی JPG کو تاریخ اور موقع کے حساب سے منظم فولڈرز میں محفوظ کریں۔ 2026-11-family-trip نامی فولڈر سالوں بعد ڈھونڈنا آسان ہوتا ہے، جبکہ DCIM نامی فولڈر نہیں ہوتا۔</p>\n<h2 id=\"archiving-converted-jpgs-bmp\">بدلی ہوئی JPG آرکائیو کرنا</h2>\n<p>بدلی ہوئی JPG بھی کسی بھی آرکائیو جیسی ہی دیکھ بھال کی حقدار ہیں۔ انہیں تاریخ اور مقصد کے حساب سے منظم فولڈرز میں محفوظ کریں، تاکہ دو سال پرانی فائل پھر بھی مل سکے۔</p>\n<p>اصل BMP کو الگ آرکائیو فولڈر میں رکھیں۔ وہ ماسٹر ہیں، اور واضح علیحدگی دونوں سیٹوں کو ملنے سے بچاتی ہے۔</p>\n<p>بدلی ہوئی فائلوں کے نام مقصد سے رکھیں، تاریخ سے نہیں۔ invoice-2024-03.jpg جیسا نام سالوں بعد مفید ہوتا ہے، جبکہ scan001.jpg جیسا نام نہیں ہوتا۔</p>\n<p>آرکائیو کا دو جگہوں پر بیک اپ رکھیں۔ مقامی ڈرائیو اور کلاؤڈ بیک اپ ہارڈ ویئر کی ناکامی، چوری اور حادثاتی حذف سے بچاتے ہیں۔</p>\n<p>آرکائیو کا ہر سال یا دو سال بعد جائزہ لیں۔ پرانے اسکین اور اسکرین شاٹس جو اب اہمیت نہیں رکھتے انہیں حذف کیا جا سکتا ہے، اور اہم فائلوں کے لیے جگہ آزاد ہو جاتی ہے۔</p>\n<p>اپنی BMP فائلیں سکڑنے کے لیے تیار ہیں؟ <a href=\"/ur/bmp-ko-jpg-mein-convert-karein/\">BMP to JPG tool</a> کھولیں اور انہیں ڈالیں۔ مراحل کے لیے <a href=\"/ur/blog/bmp-ko-jpg-mein-kaise-convert-karein/\">How to Convert BMP to JPG</a> پڑھیں، اور سائز کے سوال کے لیے <a href=\"/ur/blog/bmp-vs-jpg-file-size/\">BMP vs JPG: Why BMP Files Are So Large</a> دیکھیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"BMP فائلیں JPG سے اتنی بڑی کیوں ہوتی ہیں؟","answer":"BMP ہر پکسل کو تقریباً بغیر کمپریشن کے بالکل محفوظ کرتا ہے، اس لیے 1920 بائی 1080 اسکرین شاٹ کو صرف پکسلز کے لیے 6MB سے زیادہ چاہیے ہوتا ہے۔ JPG وہ تفصیل ضائع کرتا ہے جو آنکھ بمشکل محسوس کرتی ہے، اور اسی تصویر کو 500KB تک کمپریس کرتا ہے۔"},{"question":"BMP کو JPG میں بدلنے سے کتنی فائل سائز بچت کی توقع کروں؟","answer":"عام طور پر 90 فیصد یا اس سے زیادہ۔ 10MB اسکین شدہ BMP اکثر 85 فیصد کوالٹی پر 300KB JPG بن جاتا ہے، اور 6MB اسکرین شاٹ 500KB بن جاتا ہے۔ سادہ اسکین سب سے زیادہ بچاتے ہیں، جبکہ شور والی تصاویر کم بچاتی ہیں۔"},{"question":"BMP اسکرین شاٹس کو پڑھنے کے قابل رکھنے والی کوالٹی سیٹنگ کون سی ہے؟","answer":"اسکرین شاٹس کے لیے 85 فیصد بہترین نقطہ ہے، جو انٹرفیس متن کو صاف رکھتا ہے جبکہ فائل کو 90 فیصد سکڑتا ہے۔ چھوٹی پرنٹ والے اسکین شدہ دستاویزات کے لیے 85 سے 90 فیصد استعمال کریں۔ 75 فیصد سے نیچے چھوٹا متن دھندلا ہونے لگتا ہے۔"},{"question":"قبول کی جانے والی سب سے بڑی BMP فائل کون سی ہے؟","answer":"ہر BMP فائل 25MB تک ہو سکتی ہے، جو بڑے اسکرین شاٹس اور اعلیٰ ریزولوشن اسکین کو پورا کرتی ہے۔ چونکہ تبدیلی آپ کے ڈیوائس پر چلتی ہے، بڑی فائلیں مقامی رفتار سے پروسیس ہوتی ہیں بغیر اپ لوڈ کے انتظار کے۔"},{"question":"کیا پرانی 1 بٹ یا 8 بٹ BMP فائلیں بدلی جا سکتی ہیں؟","answer":"ہاں۔ کنورٹر 1 بٹ سیاہ سفید BMP، 8 بٹ پیلیٹ BMP، اور 24 بٹ مکمل رنگ BMP پڑھتا ہے۔ پیلیٹ رنگ JPG میں عام RGB رنگ بن جاتے ہیں، اور تصویر ایک جیسی لگتی ہے۔ بہت پرانی قسم بھی عام طور پر کام کرتی ہے۔"},{"question":"BMP سے JPG کب BMP سے PNG سے بہتر ہے؟","answer":"جب مقصد چھوٹی فائلیں ہوں۔ JPG میں بدلا BMP اسکین 90 فیصد یا اس سے زیادہ سکڑ جاتا ہے، جبکہ PNG ورژن کہیں کم سکڑتا ہے۔ PNG صرف تب چنیں جب تصویر کو کئی بار ایڈٹ کیا جائے گا، کیونکہ PNG لاس لیس ہے۔"}];
